/* aesthetic figures v2.17.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-ok: #15714b;
  --ae-warn: #8a5f32;
  --ae-err: #a84138;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-ok-dark: #6fd2a8;
  --ae-warn-dark: #c49d72;
  --ae-err-dark: #e58379;
  --ae-w-black: 800;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
    --ae-ok: var(--ae-ok-dark);
    --ae-warn: var(--ae-warn-dark);
    --ae-err: var(--ae-err-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

.dark,
[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
  --ae-ok: var(--ae-ok-dark);
  --ae-warn: var(--ae-warn-dark);
  --ae-err: var(--ae-err-dark);
}

.ae-icon {
width: 1.2em;
  height: 1.2em;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
  vertical-align: -0.2em;
}

.ae-dim {
color: var(--ae-ink-muted);
}

.ae-ok {
color: var(--ae-ok);
}

.ae-warn {
color: var(--ae-warn);
}

.ae-err {
color: var(--ae-err);
}

.ae-num {
font-family: var(--ae-font-mono);
  font-variant-numeric: tabular-nums;
}

.ae-strong {
font-weight: var(--ae-w-black);
}

.ae-delta {
display: inline-flex;
  align-items: baseline;
  gap: 0.35em;
}

.ae-spark {
width: 7em;
  height: 1.1em;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
  vertical-align: -0.15em;
}
